INSERT INTO `products` (`id`, `slug`, `name`, `short_description`, `long_description`, `price`, `sale_price`, `category`, `stock_quantity`, `image_main`, `image_gallery`, `meta_title`, `meta_description`, `meta_keywords`, `is_featured`, `is_active`, `created_at`, `updated_at`) VALUES (6, 'almond-halwa-spread', 'Almond Halwa Spread', 'The richness of Indian almond halwa, reinvented into a clean, creamy and versatile spread made with minimal ingredients for pure, modern indulgence.', 'India’s beloved almond halwa, reinvented as a clean, luxurious spread.

Made with minimal, carefully chosen ingredients, this smooth and naturally nutty spread brings together the richness of almonds and the delicate warmth of cardamom without unnecessary additives. Clean-label, wholesome and crafted for modern indulgence, it is as versatile as it is delicious.

Spread it on toast, croissants and pancakes, swirl it into desserts, or use it to create bonbon fillings, chocolate confections and pastry creations.

A traditional favourite. A modern innovation. One irresistibly versatile jar.', 350.00, 299.00, 'Spreads & Nut Butters', 50, 'assets/products/prod-almond-halwa-spread-1790077418.png', '[]', 'Almond Halwa Spread | Clean Label | RT Chocos | Innovative recipe', 'Discover Almond Halwa Spread by RT Chocos—a creamy, nutty, clean-label indulgence made with minimal ingredients. Perfect for toast, desserts & bonbons.', 'almond halwa spread, almond spread, halwa spread, Indian almond spread, clean label spread, gourmet almond spread, almond spread India, RT Chocos, Innovative recipe, bestdiwaligifting, corporategifting,', 1, 1, '2026-09-05 09:07:25', '2026-09-22 11:43:38') ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `short_description`=VALUES(`short_description`), `long_description`=VALUES(`long_description`), `price`=VALUES(`price`), `sale_price`=VALUES(`sale_price`), `stock_quantity`=VALUES(`stock_quantity`), `image_main`=VALUES(`image_main`), `meta_title`=VALUES(`meta_title`), `meta_description`=VALUES(`meta_description`);
INSERT INTO `products` (`id`, `slug`, `name`, `short_description`, `long_description`, `price`, `sale_price`, `category`, `stock_quantity`, `image_main`, `image_gallery`, `meta_title`, `meta_description`, `meta_keywords`, `is_featured`, `is_active`, `created_at`, `updated_at`) VALUES (7, 'cashew-coconut-spread', 'Cashew Coconut Spread', 'A silky-smooth blend of lightly roasted cashews and coconut, stone-ground in small batches for a rich, creamy texture. Clean, indulgent and endlessly versatile from toast and smoothies to desserts, pastries and bonbons.', 'A tropical indulgence, crafted in small batches.

Lightly roasted whole cashews and coconut are slowly stone-ground in small batches, creating an exceptionally silky, creamy texture with rich cashew notes and a delicate coconut finish. Made with minimal ingredients, with no palm oil or artificial preservatives.

Perfect on toast, croissants and fresh fruit, or elevate smoothie bowls, dessert frostings, cakes, pastries, bonbon fillings and chocolate creations.

Slow-crafted. Silky-smooth. Naturally indulgent.', 390.00, 360.00, 'Spreads & Nut Butters', 45, 'assets/products/prod-cashew-coconut-spread-1790015793.png', '[]', 'Cashew Coconut Spread | Innovative  Recipe | Gourmet Diwali & Corporate Gifts', 'Discover RT Chocos Cashew Coconut Spread, stone-ground in small batches for a silky texture. Perfect for toast, desserts, bonbons, Diwali & corporate gifting.', 'cashew coconut spread, cashew spread, cashew butter, coconut spread, gourmet nut butter, clean label spread, premium Diwali gifts, Diwali gifting, corporate gifting, corporate gifts India, gourmet gifting, premium food gifts, RT Chocos', 1, 1, '2026-09-05 09:07:25', '2026-09-21 18:36:33') ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `short_description`=VALUES(`short_description`), `long_description`=VALUES(`long_description`), `price`=VALUES(`price`), `sale_price`=VALUES(`sale_price`), `stock_quantity`=VALUES(`stock_quantity`), `image_main`=VALUES(`image_main`), `meta_title`=VALUES(`meta_title`), `meta_description`=VALUES(`meta_description`);
INSERT INTO `products` (`id`, `slug`, `name`, `short_description`, `long_description`, `price`, `sale_price`, `category`, `stock_quantity`, `image_main`, `image_gallery`, `meta_title`, `meta_description`, `meta_keywords`, `is_featured`, `is_active`, `created_at`, `updated_at`) VALUES (9, 'almond-spread', 'Crunchy Almond Spread', 'A clean-label, minimally processed almond spread, stone-ground in small batches from premium almonds for a rich, creamy texture and irresistible crunch. Perfect for everyday indulgence, desserts, bonbons, and premium Diwali & corporate gifting.', 'Pure almond indulgence, crafted with a delicious crunch. Made from premium almonds and minimal ingredients, this clean-label, minimally processed spread is stone-ground and crafted in small batches for exceptional creaminess with an irresistible almond crunch.

Perfect for toast, croissants, desserts, pastries and bonbons and beautifully suited for premium Diwali and corporate gifting.

Clean. Crafted. Crunchy. Unmistakably indulgent.', 360.00, 325.00, 'Spreads & Nut Butters', 70, 'assets/products/prod-almond-spread-1790015745.png', '[]', 'Crunchy Almond Spread | Premium Nut Butter | RT Chocos', 'RT Chocos Crunchy Almond Spread ,premium almonds, stone-ground in small batches for creamy richness and crunch. A perfect choice for Diwali & corporate gifting.', 'crunchy almond spread, almond spread, almond butter, premium almond spread, almond spread India, clean label spread, stone ground almond spread, gourmet nut butter, Diwali gifting, Diwali gifts, Diwali corporate gifting, corporate gifting, corporate gifts India, premium corporate gifts, gourmet Diwali gifts, festive gifting, premium food gifts, RT Chocos', 1, 1, '2026-09-05 09:07:25', '2026-09-21 18:35:45') ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `short_description`=VALUES(`short_description`), `long_description`=VALUES(`long_description`), `price`=VALUES(`price`), `sale_price`=VALUES(`sale_price`), `stock_quantity`=VALUES(`stock_quantity`), `image_main`=VALUES(`image_main`), `meta_title`=VALUES(`meta_title`), `meta_description`=VALUES(`meta_description`);
